from math import sqrt, isclose

def max_fruits_sliced(n, fruits):
    def distance(p1, p2):
        return sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

    def is_on_circle(p, c, r):
        return isclose(distance(p, c), r, rel_tol=1e-9)

    def line_contains_point(p1, p2, p):
        if p1 == p2:
            return is_on_circle(p, p1, 1.0)
        # Calculate the intersection of the perpendicular bisector and the line passing through p1 and p2
        mid_x = (p1[0] + p2[0]) / 2
        mid_y = (p1[1] + p2[1]) / 2
        p2_p1_x = p2[0] - p1[0]
        p2_p1_y = p2[1] - p1[1]
        if abs(p2_p1_x) < 1e-9:  # vertical line
            return isclose(p[0], mid_x, rel_tol=1e-9)
        slope_perp = -p2_p1_y / p2_p1_x
        bisector_x = mid_x + (mid_y - slope_perp * mid_x) / (1 + slope_perp ** 2)
        if not isclose(bisector_x, (mid_x + mid_y) / 2 + (mid_y - slope_perp * mid_x) / (2 * (1 + slope_perp ** 2)), rel_tol=1e-9):
            bisector_x = mid_x - (mid_y - slope_perp * mid_x) / (1 + slope_perp ** 2)
        bisector_y = slope_perp * bisector_x + (mid_y - slope_perp * mid_x)
        # Check if this intersection point is on the segment p1-p2
        cross_product_1 = (p2[0] - p1[0]) * (bisector_y - p1[1]) - (p2[1] - p1[1]) * (bisector_x - p1[0])
        cross_product_2 = (p2[0] - p1[0]) * (p[1] - p1[1]) - (p2[1] - p1[1]) * (p[0] - p1[0])
        return cross_product_1 * cross_product_2 >= 0 and is_on_circle((bisector_x, bisector_y), p1, distance(p1, p2) / 2)

    max_sliced = 0

    for i, j in combinations(range(n), 2):
        sliced = 0
        for k in range(n):
            if line_contains_point(fruits[i], fruits[j], fruits[k]):
                sliced += 1
        max_sliced = max(max_sliced, sliced)

    return max_sliced

