import sys
from math import gcd, isclose
from collections import defaultdict

def max_fruits_on_slice(n, points):
    def get_angle(dx, dy):
        if dx == 0:
            return (0, 1) if dy > 0 else (0, -1)
        if dy == 0:
            return (1, 0) if dx > 0 else (-1, 0)
        g = gcd(dx, dy)
        dx, dy = dx // g, dy // g
        if dx < 0:
            dx, dy = -dx, -dy
        elif dx == 0 and dy < 0:
            dy = -dy
        return (dx, dy)

    slopes = defaultdict(set)

    for i in range(n):
        x1, y1 = points[i]
        for j in range(i + 1, n):
            x2, y2 = points[j]
            dx = x2 - x1
            dy = y2 - y1
            angle = get_angle(dx, dy)
            slopes[angle].add(i)
            slopes[angle].add(j)

    max_fruits = 0
    for fruit_set in slopes.values():
        max_fruits = max(max_fruits, len(fruit_set))

    return max_fruits

