from itertools import combinations

def max_fruits_sliced(n, fruits):
    def distance(p1, p2):
        return sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

    def angle(p1, p2):
        return atan2(p2[1] - p1[1], p2[0] - p1[0])

    def is_intersecting(p1, p2, fruit):
        d = distance(p1, p2)
        if d == 0:
            return distance(p1, fruit) <= 1
        t = ((fruit[0] - p1[0]) * (p2[0] - p1[0]) + (fruit[1] - p1[1]) * (p2[1] - p1[1])) / (d**2)
        t = max(0, min(1, t))
        closest = (p1[0] + t * (p2[0] - p1[0]), p1[1] + t * (p2[1] - p1[1]))
        return distance(closest, fruit) <= 1

    max_fruits = 1
    for p1, p2 in combinations(fruits, 2):
        count = sum(1 for fruit in fruits if is_intersecting(p1, p2, fruit))
        max_fruits = max(max_fruits, count)

    return max_fruits

def main():
    n = int(sys.stdin.readline().strip())
